/**
 * Scoped to this atom's own contract per testing.md: given a name or an empty one, does it render
 * the right branch.
 *
 * The heading level is deliberately not re-asserted here — `index.stories.tsx`'s `Default` and
 * `HeadingLevels` plays already pin the role and level for all three `as` values, and duplicating
 * that at this layer would be the cross-layer duplication testing.md rules out. What no other
 * layer covers is the empty-name branch: `ZimmProductContent`'s stories always pass a real name,
 * and the page's own mapper short-circuits before this atom is reached, so nothing else proves
 * this atom collapses rather than rendering an empty heading.
 */
import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ZimmProductName } from './index';

describe('ZimmProductName', () => {
  test('renders the name it is handed', () => {
    render(<ZimmProductName name="Natura Long Sleeve Linen Mini Dress" as="h2" />);
    expect(screen.getByTestId('product-name').textContent).toBe('Natura Long Sleeve Linen Mini Dress');
  });

  test('renders nothing for an empty name', () => {
    const { container } = render(<ZimmProductName name="" as="h2" />);

    // `name` is typed `string`, so TypeScript rules out an absent name but not an empty one. An
    // empty `heading3` node is not free: it keeps its row in `ZimmProductContent`'s flex column
    // and consumes the column's 20px `gap`, leaving a visible hole above the price.
    //
    // Asserted as an empty container rather than an absent testid, for the same reason
    // `zimmProductPrice/index.test.tsx` does it: a node that still carried the recipe's styling
    // but had lost its `data-testid` would satisfy the narrower check while being precisely the
    // gap-consuming element this guard exists to prevent.
    expect(container).toBeEmptyDOMElement();
  });
});

