  test('component overrides are registered', () => {
    // ListMenu in particular: the base component reads
    // theme.components.ListMenu.baseStyle directly, so a missing entry throws
    // at render rather than falling back.
    expect(theme.components.Button).toBeTruthy();
    expect(theme.components.Header).toBeTruthy();
    expect(theme.components.ListMenu).toBeTruthy();

    // The opposite failure mode, and the reason this list stays hand-maintained rather than
    // derived from the `components` map — a derived list moves with any unregistration and so
    // could never catch one. Where ListMenu throws, these three fail silently: `useStyleConfig`
    // and `useMultiStyleConfig` return an empty object for an unregistered recipe,
    // `__css={undefined}` is a legal prop, and the element quietly inherits instead. For the two
    // atoms the whole recipe is `margin: 0` and one colour, so an unregistration is very nearly
    // invisible: the base template's own `styles.js` sets `color: 'gray.900'` on the body, and the
    // gray scale in play is SFCC's, not Chakra's — its `foundations/colors.js` replaces the whole
    // scale before our overrides merge. SFCC's `gray.900` is #181818 against the brand's #191919,
    // one unit per channel, which no visual review will catch. ZimmProductMeta's resolved 28px is
    // additionally pinned in its own suite; the two atoms have only this.
    expect(theme.components.ZimmProductMeta).toBeTruthy();
    expect(theme.components.ZimmProductName).toBeTruthy();
    expect(theme.components.ZimmProductModelInfo).toBeTruthy();
  });
});

describe('scale token collisions — Chakra keeps its own meanings', () => {
  test('fontSizes are NOT remapped to the Zimmermann scale', () => {
    // Design system: md 24px, xs 16px, 2xs 14px, 3xs 12px, 4xs 10px.
    // Chakra: md 16px, xs 12px, 2xs 10px, 3xs 7.2px — four collisions.
    // Type is set via `textStyle`, never a raw `fontSize` token, precisely so
    // these two scales never have to agree. If this test fails, someone has
    // remapped the scale and every base-component `fontSize` shifted with it.
    expect(theme.fontSizes.md).toBe('1rem');
    expect(theme.fontSizes.xs).toBe('0.75rem');
    expect(theme.fontSizes['2xs']).toBe('0.625rem');
